#include "core/suspended_sale_service.h"
#include "core/database.h"
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
namespace pos { SuspendedSaleService::SuspendedSaleService(std::shared_ptr<Database> database):db_(std::move(database)){} QString SuspendedSaleService::save(const QList<SuspendedLine>& lines){if(lines.isEmpty())throw DatabaseError("cannot suspend an empty sale");QJsonArray array;for(const auto& line:lines){if(line.productId.isEmpty()||line.quantity<=0||line.unitPrice<0)throw DatabaseError("invalid suspended sale line");QJsonObject object;object["product_id"]=line.productId;object["quantity"]=QString::number(line.quantity);object["unit_price"]=QString::number(line.unitPrice);object["unit"]=line.unit;array.append(object);}Transaction tx(db_->handle());const auto id=uuid();auto q=db_->prepare("INSERT INTO suspended_sales(id,label,cart_json,created_at) VALUES(?,?,?,?)");q.bind(1,id);q.bind(2,"Suspended sale");q.bind(3,QString::fromUtf8(QJsonDocument(array).toJson(QJsonDocument::Compact)));q.bind(4,utcNow());q.execute();tx.commit();return id;} QList<SuspendedSale> SuspendedSaleService::list()const{QList<SuspendedSale> result;auto q=db_->prepare("SELECT id,created_at FROM suspended_sales ORDER BY created_at DESC");while(q.stepRow())result.append({q.text(0),q.text(1),{}});return result;} SuspendedSale SuspendedSaleService::load(const QString& id)const{auto q=db_->prepare("SELECT id,cart_json,created_at FROM suspended_sales WHERE id=?");q.bind(1,id);if(!q.stepRow())throw DatabaseError("suspended sale not found");const auto document=QJsonDocument::fromJson(q.text(1).toUtf8());if(!document.isArray())throw DatabaseError("suspended sale data is corrupt");SuspendedSale result{q.text(0),q.text(2),{}};for(const auto value:document.array()){const auto object=value.toObject();bool quantityOk=false,priceOk=false;const auto quantity=object.value("quantity").toString().toLongLong(&quantityOk);const auto price=object.value("unit_price").toString().toLongLong(&priceOk);if(!quantityOk||!priceOk)throw DatabaseError("suspended sale data is corrupt");result.lines.append({object.value("product_id").toString(),quantity,price,object.value("unit").toString()});}return result;} void SuspendedSaleService::remove(const QString& id){Transaction tx(db_->handle());auto q=db_->prepare("DELETE FROM suspended_sales WHERE id=?");q.bind(1,id);q.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("suspended sale not found");tx.commit();} }
